func (s PurchaseState) Validate() error {
	switch s {
	case "submitted":
		return nil
	case "checkout_create_reserved":
		return nil
	case "checkout_unknown":
		return nil
	case "checkout_open":
		return nil
	case "order_ready":
		return nil
	case "accept_unknown":
		return nil
	case "accepted":
		return nil
	case "create_unknown":
		return nil
	case "awaiting_delivery":
		return nil
	case "delivered":
		return nil
	case "settle_unknown":
		return nil
	case "completed":
		return nil
	case "rejected":
		return nil
	case "provider_rejected":
		return nil
	default:
		return errors.Errorf("invalid value: %v", s)
	}
}

func (s *RefundProgress) Validate() error {
	if s == nil {
		return validate.ErrNilPointer
	}

	var failures []validate.FieldError
	if err := func() error {
		if err := s.CancellationState.Validate(); err != nil {
			return err
		}
		return nil
	}(); err != nil {
		failures = append(failures, validate.FieldError{
			Name:  "cancellation_state",
			Error: err,
		})
	}
	if len(failures) > 0 {
		return &validate.Error{Fields: failures}
	}
	return nil
}

func (s RefundProgressCancellationState) Validate() error {
	switch s {
	case "requested":
		return nil
	case "scheduled":
		return nil
	case "releasing":
		return nil
	case "completed":
		return nil
	case "canceled":
		return nil
	case "failed":
		return nil
	default:
		return errors.Errorf("invalid value: %v", s)
	}
}
